func testEstadoToManyRemoveOpEstIDFimConhecimentoTransportes(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Estado
	var b, c, d, e ConhecimentoTransporte

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, estadoDBTypes, false, strmangle.SetComplement(estadoPrimaryKeyColumns, estadoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ConhecimentoTransporte{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, conhecimentoTransporteDBTypes, false, strmangle.SetComplement(conhecimentoTransportePrimaryKeyColumns, conhecimentoTransporteColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddEstIDFimConhecimentoTransportes(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.EstIDFimConhecimentoTransportes().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveEstIDFimConhecimentoTransportes(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.EstIDFimConhecimentoTransportes().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.EstIDFim) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.EstIDFim) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.EstIDFimEstado != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.EstIDFimEstado != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.EstIDFimEstado != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.EstIDFimEstado != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.EstIDFimConhecimentoTransportes) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.EstIDFimConhecimentoTransportes[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.EstIDFimConhecimentoTransportes[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

