func testEstadoToManySetOpEstNotaFiscals(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Estado
	var b, c, d, e NotaFiscal

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, estadoDBTypes, false, strmangle.SetComplement(estadoPrimaryKeyColumns, estadoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*NotaFiscal{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, notaFiscalDBTypes, false, strmangle.SetComplement(notaFiscalPrimaryKeyColumns, notaFiscalColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetEstNotaFiscals(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.EstNotaFiscals().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetEstNotaFiscals(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.EstNotaFiscals().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.EstID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.EstID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.EstID, d.EstID) {
		t.Error("foreign key was wrong value", a.EstID, d.EstID)
	}
	if !queries.Equal(a.EstID, e.EstID) {
		t.Error("foreign key was wrong value", a.EstID, e.EstID)
	}

	if b.R.Est != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Est != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Est != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Est != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.EstNotaFiscals[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.EstNotaFiscals[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

func testEstadoToManyRemoveOpEstNotaFiscals(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Estado
	var b, c, d, e NotaFiscal

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, estadoDBTypes, false, strmangle.SetComplement(estadoPrimaryKeyColumns, estadoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*NotaFiscal{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, notaFiscalDBTypes, false, strmangle.SetComplement(notaFiscalPrimaryKeyColumns, notaFiscalColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddEstNotaFiscals(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.EstNotaFiscals().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveEstNotaFiscals(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.EstNotaFiscals().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.EstID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.EstID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Est != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Est != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Est != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Est != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.EstNotaFiscals) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.EstNotaFiscals[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.EstNotaFiscals[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

