func testEstadoToManyAddOpEstNotaFiscalItemImportacaos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Estado
	var b, c, d, e NotaFiscalItemImportacao

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, estadoDBTypes, false, strmangle.SetComplement(estadoPrimaryKeyColumns, estadoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*NotaFiscalItemImportacao{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, notaFiscalItemImportacaoDBTypes, false, strmangle.SetComplement(notaFiscalItemImportacaoPrimaryKeyColumns, notaFiscalItemImportacaoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*NotaFiscalItemImportacao{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddEstNotaFiscalItemImportacaos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.EstID != first.EstID {
			t.Error("foreign key was wrong value", a.EstID, first.EstID)
		}
		if a.EstID != second.EstID {
			t.Error("foreign key was wrong value", a.EstID, second.EstID)
		}

		if first.R.Est != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Est != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.EstNotaFiscalItemImportacaos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.EstNotaFiscalItemImportacaos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.EstNotaFiscalItemImportacaos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

